import pytest
import torch

import flag_gems

from . import accuracy_utils as utils


def _missing_cpu_lapack(inp):
    """MUSA CPU builds can lack LAPACK, so linear-algebra references fall back
    to NumPy. This mirrors the MUSA reference pattern used on master
    (tests/test_inverse.py, test_linalg_lu_solve.py, test_det.py)."""
    return (
        flag_gems.vendor_name == "mthreads"
        and inp.device.type == "cpu"
        and not torch._C.has_lapack
    )


def _reference_input(inp, upcast=False):
    # On MUSA the reference is taken on CPU; other vendors keep the existing
    # device/--ref cpu behaviour.
    source = inp.cpu() if flag_gems.vendor_name == "mthreads" else inp
    return utils.to_reference(source, upcast)


def _from_numpy(value):
    import numpy as np

    return torch.from_numpy(np.array(value, copy=True))


def _assert_target_abi(actual, reference, inp):
    if isinstance(actual, (tuple, list)):
        assert isinstance(reference, (tuple, list)) and len(actual) == len(reference)
        for value, expected in zip(actual, reference):
            _assert_target_abi(value, expected, inp)
        return
    assert isinstance(actual, torch.Tensor)
    assert actual.device == inp.device
    assert actual.dtype == inp.dtype
    assert actual.shape == reference.shape
    assert actual.untyped_storage()._cdata != inp.untyped_storage()._cdata


def _for_comparison(actual, reference, inp):
    # Inspect the requested target ABI before CPU observation/value comparison.
    _assert_target_abi(actual, reference, inp)
    return actual.cpu() if flag_gems.vendor_name == "mthreads" else actual


def _reference_qr(inp):
    if _missing_cpu_lapack(inp):
        import numpy as np

        return tuple(_from_numpy(x) for x in np.linalg.qr(inp.detach().numpy()))
    return torch.linalg.qr(inp)


def _reference_pinv(inp):
    if _missing_cpu_lapack(inp):
        import numpy as np

        array = inp.detach().numpy()
        # torch.linalg.pinv's original default cutoff is dtype/geometry
        # dependent; keep the test-repair rtol semantics.
        rtol = max(array.shape[-2:]) * np.finfo(array.dtype).eps
        return _from_numpy(np.linalg.pinv(array, rcond=rtol))
    return torch.linalg.pinv(inp)


@pytest.fixture(autouse=True)
def _ieee_fp32_matmul():
    # The blocked Jacobi path rebuilds pinv with a native fp32 matmul.  Runners
    # that start torch with TF32 enabled (TORCH_ALLOW_TF32_CUBLAS_OVERRIDE=1 is
    # set on CI's a100-worker-1) then evaluate that matmul with a 10-bit
    # mantissa, which moves the result ~1e-4 away from the cuSOLVER reference
    # on (48, 48) -- the fused path never uses a matmul and stays at ~3e-7.
    # That is an ambient precision policy, not a property of the kernel under
    # test, so pin both precision APIs off (torch >= 2.9 new API plus the legacy
    # flag, which older versions only have) and restore the process state
    # afterwards.  Same approach as tests/test_chain_matmul.py.
    saved_precision = None
    try:
        saved_precision = torch.backends.cuda.matmul.fp32_precision
    except (AttributeError, RuntimeError):
        pass
    saved_tf32 = None
    try:
        saved_tf32 = torch.backends.cuda.matmul.allow_tf32
    except (AttributeError, RuntimeError):
        pass
    try:
        torch.backends.cuda.matmul.fp32_precision = "ieee"
    except (AttributeError, RuntimeError):
        pass
    try:
        torch.backends.cuda.matmul.allow_tf32 = False
    except (AttributeError, RuntimeError):
        pass
    yield
    if saved_precision is not None:
        try:
            torch.backends.cuda.matmul.fp32_precision = saved_precision
        except (AttributeError, RuntimeError):
            pass
    if saved_tf32 is not None:
        try:
            torch.backends.cuda.matmul.allow_tf32 = saved_tf32
        except (AttributeError, RuntimeError):
            pass


# Jacobi SVD kernel operates in float32; float16/bfloat16 lack precision for convergence
PINV_DTYPES = [torch.float32]

# Test shapes: (m, n) - square matrices only
# Rectangular matrices have lower SVD precision with fixed Jacobi sweep count
# n <= 8 due to Triton static_range compile time for larger sizes
PINV_SHAPES = [(4, 4), (8, 8)]

# Shapes above the fused kernel's 32-element limit, which route to the blocked
# Jacobi path. Kept small because the reference pinv runs on CPU under --ref=cpu.
PINV_LARGE_SHAPES = [(48, 48), (64, 40), (40, 64)]


def _well_conditioned(m, n, dtype, seed=0):
    """Build a (m, n) matrix with a known, tightly bounded singular spectrum.

    `randn(m, n) + 2 * I` leaves the condition number uncontrolled (observed in
    the hundreds to thousands), and pinv error grows with cond * eps, so that
    construction makes the tolerance check seed-dependent: it passed or failed
    depending on which matrix was drawn. Composing an explicit SVD with
    singular values in [1, 2] pins cond <= 2 instead, for both the fused and
    the blocked kernel paths.
    """
    g = torch.Generator(device="cpu").manual_seed(seed)
    k = min(m, n)
    # Orthonormal factors via QR of fixed-seed gaussians.
    u, _ = _reference_qr(torch.randn(m, k, generator=g))
    v, _ = _reference_qr(torch.randn(n, k, generator=g))
    s = torch.linspace(2.0, 1.0, k)
    A = (u * s) @ v.T
    return A.to(dtype).to(flag_gems.device)


@pytest.mark.linalg_pinv
@pytest.mark.parametrize("shape", PINV_SHAPES)
@pytest.mark.parametrize("dtype", PINV_DTYPES)
def test_linalg_pinv(shape, dtype):
    m, n = shape
    A = _well_conditioned(m, n, dtype)
    ref_A = _reference_input(A, True)
    ref_out = _reference_pinv(ref_A)
    res_out = flag_gems.linalg_pinv(A)
    utils.gems_assert_close(_for_comparison(res_out, ref_out, A), ref_out, dtype)


@pytest.mark.linalg_pinv
@pytest.mark.parametrize("shape", PINV_SHAPES)
@pytest.mark.parametrize("dtype", PINV_DTYPES)
def test_linalg_pinv_batched(shape, dtype):
    m, n = shape
